// The web app has one source: app/static. Android copies it at build time (copyWebApp in android/app/build.gradle),
// the web deployment is generated by tools/sync_web.sh. This test guards both and, if the generated web folder
// exists, that it is up to date.
const fs = require("fs");
const path = require("path");
const assert = require("assert");
const root = path.join(__dirname, "..");
const gradle = fs.readFileSync(path.join(root, "android/app/build.gradle"), "utf8");
assert(/from\(rootProject\.file\('\.\.\/app\/static'\)\)/.test(gradle), "Android copies the web app from app/static");
assert(!fs.existsSync(path.join(root, "android/app/src/main/assets/strato_app.js")), "no second copy in android/app/src/main/assets");
const files = ["index.html", "strato_app.js", "style.css", "pii_engine.js", "ocr_utils.js", "icon.svg"];
const vendor = fs.readdirSync(path.join(root, "app/static/vendor")).filter((f) => !f.startsWith("."));
assert(!vendor.some((f) => f.endsWith(".traineddata")), "only compressed language data (*.traineddata.gz) is shipped");
const dest = "dist/web_deployment/blackmydata/run";
if (fs.existsSync(path.join(root, dest, "vendor"))) {
  for (const f of [...files, ...vendor.map((v) => "vendor/" + v)]) {
    const a = fs.readFileSync(path.join(root, "app/static", f));
    const b = fs.readFileSync(path.join(root, dest, f));
    assert(a.equals(b), `${dest}/${f} is outdated – run tools/sync_web.sh`);
  }
  console.log(`  ✓ ${dest} is up to date`);
}
console.log("  ✓ single source app/static");

// BMD-R6: the version literals in app/static (fallback when the source folder runs directly) equal versionName in
// android/app/build.gradle, the one version source. The release workflow stamps them with tools/version.sh.
const versionName = (gradle.match(/^\s*versionName\s+'(\d+\.\d+\.\d+)'/m) || [])[1];
assert(versionName, "versionName X.Y.Z in android/app/build.gradle");
const appJs = fs.readFileSync(path.join(root, "app/static/strato_app.js"), "utf8");
assert.strictEqual((appJs.match(/^const CURRENT_BUILD_VERSION = "([^"]*)";/m) || [])[1], versionName,
  "CURRENT_BUILD_VERSION in app/static/strato_app.js equals versionName – run tools/version.sh --stamp");
const indexHtml = fs.readFileSync(path.join(root, "app/static/index.html"), "utf8");
const busters = [...indexHtml.matchAll(/\?v=(\d+\.\d+\.\d+)"/g)].map((m) => m[1]);
assert(busters.length > 0 && busters.every((v) => v === versionName),
  `?v= cache busters in app/static/index.html equal versionName ${versionName} – run tools/version.sh --stamp`);
// Visible labels carry no hard-coded version of their own: they are <span class="app-version"> filled from
// CURRENT_BUILD_VERSION at runtime (a stale "v1.0.0" badge stood in the privacy card up to 1.0.4).
assert(/<span class="app-version">/.test(indexHtml), 'index.html shows the version through <span class="app-version">');
const stale = [...indexHtml.matchAll(/[•>]\s*v(\d+\.\d+\.\d+)\s*</g)].map((m) => m[1]);
assert.deepStrictEqual(stale, [], `hard-coded visible versions in index.html: ${stale.join(", ")} – use <span class="app-version">`);
console.log(`  ✓ version literals in app/static match versionName ${versionName}`);

// GitHub review 2026-11-25: every package ships the license texts (Apache-2.0 §4(a), MIT/BSD/Zlib notices).
// app/static/licenses is the one source; app/static/licenses/LICENSE.txt is a copy of the project LICENSE (GPL-3.0),
// app/static/licenses/LICENSE-EXCEPTIONS.txt a copy of LICENSE-EXCEPTIONS.md (section 7 terms).
const lic = path.join(root, "app/static/licenses");
for (const f of ["LICENSE.txt", "LICENSE-EXCEPTIONS.txt", "THIRD_PARTY_NOTICES.txt", "Apache-2.0.txt"]) {
  assert(fs.existsSync(path.join(lic, f)), `app/static/licenses/${f} exists`);
}
assert(fs.readFileSync(path.join(root, "LICENSE")).equals(fs.readFileSync(path.join(lic, "LICENSE.txt"))),
  "app/static/licenses/LICENSE.txt equals LICENSE – copy it again");
assert(/GNU GENERAL PUBLIC LICENSE\s+Version 3, 29 June 2007/.test(fs.readFileSync(path.join(root, "LICENSE"), "utf8")) &&
  /END OF TERMS AND CONDITIONS/.test(fs.readFileSync(path.join(root, "LICENSE"), "utf8")), "LICENSE is the full GPL-3.0 text");
assert(fs.readFileSync(path.join(root, "LICENSE-EXCEPTIONS.md")).equals(fs.readFileSync(path.join(lic, "LICENSE-EXCEPTIONS.txt"))),
  "app/static/licenses/LICENSE-EXCEPTIONS.txt equals LICENSE-EXCEPTIONS.md – copy it again");
assert(/END OF TERMS AND CONDITIONS/.test(fs.readFileSync(path.join(lic, "Apache-2.0.txt"), "utf8")), "full Apache-2.0 text");
const notices = fs.readFileSync(path.join(lic, "THIRD_PARTY_NOTICES.txt"), "utf8");
for (const c of ["PDF.js", "Tesseract.js", "Leptonica", "libpng", "zlib", "libtiff", "JSZip", "pdf-lib", "pako", "tslib",
  "AndroidX", "Kotlin", "Go standard library"]) {
  assert(notices.includes(c), `THIRD_PARTY_NOTICES.txt names ${c}`);
}
// jsPDF (with md5.js of unclear license) was removed; pdf-lib writes all PDFs.
assert(!/jsPDF|md5\.js/.test(notices), "THIRD_PARTY_NOTICES.txt no longer lists jsPDF/md5.js");
assert(!vendor.some((f) => /jspdf/i.test(f)), "no jsPDF in app/static/vendor");
for (const f of ["tesseract.min.js.LICENSE.txt", "worker.min.js.LICENSE.txt"]) {
  assert(vendor.includes(f), `vendor/${f} (referenced by the bundle header) exists`);
}
// Android copies all of app/static (licenses included); the desktop builds and the web sync copy the folder explicitly.
for (const s of ["macos/build-app.sh", "linux/build.sh", "windows/build.sh", "windows/installer.nsi", "tools/sync_web.sh"]) {
  assert(/app\/static\/licenses|\$SRC\/licenses/.test(fs.readFileSync(path.join(root, s), "utf8")), `${s} ships app/static/licenses`);
}
assert(!/exclude[^\n]*licenses/.test(gradle), "copyWebApp does not exclude the licenses folder");
console.log("  ✓ license texts are part of every package");
